custom_qss:
QMainWindow {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #ff0000, stop:0.2 #00ff00, stop:0.4 #0000ff,
        stop:0.6 #ffff00, stop:0.8 #ff00ff, stop:1 #00ffff) !important;
}
QMenuBar {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #ff0000, stop:0.25 #00ff00, stop:0.5 #0000ff,
        stop:0.75 #ffff00, stop:1 #ff00ff) !important;
    color: #000000;
    border: 1px solid #ff0000;
}
QToolBar {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #0000ff, stop:0.25 #ffff00, stop:0.5 #ff00ff,
        stop:0.75 #00ff00, stop:1 #ff0000) !important;
    border: 1px solid #0000ff;
}
QStatusBar {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #ff00ff, stop:0.25 #ff6600, stop:0.5 #ffff00,
        stop:0.75 #00ff00, stop:1 #0000ff) !important;
    color: #000000;
    border: 1px solid #ff00ff;
}
QDockWidget {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #00ffff, stop:0.2 #ff00ff, stop:0.4 #ffff00,
        stop:0.6 #ff0000, stop:0.8 #00ff00, stop:1 #0000ff) !important;
    border: 1px solid #ff0000;
}
QDockWidget::title {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #ffff00, stop:0.25 #ff00ff, stop:0.5 #0000ff,
        stop:0.75 #ff0000, stop:1 #00ff00) !important;
    color: #000000;
    border: 1px solid #ffff00;
}
QTabBar::tab {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #ff00ff, stop:0.2 #00ffff, stop:0.4 #ffff00,
        stop:0.6 #ff0000, stop:0.8 #00ff00, stop:1 #0000ff) !important;
    color: #000000;
    border: 1px solid #ff0000;
}
QTabBar::tab:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #ff0000, stop:0.25 #00ff00, stop:0.5 #0000ff,
        stop:0.75 #ffff00, stop:1 #ff00ff) !important;
    color: #000000;
    border: 2px solid #ff0000;
}
QToolBar QToolButton {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #ffff00, stop:0.25 #ff00ff, stop:0.5 #0000ff,
        stop:0.75 #00ff00, stop:1 #ff0000) !important;
    border: 1px solid #00ff00;
    color: #000000;
}
QToolBar QToolButton:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #330000, stop:0.25 #660000, stop:0.5 #990000,
        stop:0.75 #cc0000, stop:1 #ff0000) !important;
}
QToolBar QToolButton:checked, QToolBar QToolButton:pressed {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #ff00ff, stop:0.25 #ff6600, stop:0.5 #ffff00,
        stop:0.75 #00ff00, stop:1 #0000ff) !important;
    color: #000000;
    border: 2px solid #ff6600;
}
QToolButton {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #00ff00, stop:0.25 #ffff00, stop:0.5 #ff00ff,
        stop:0.75 #0000ff, stop:1 #ff0000) !important;
    border: 1px solid #00ff00;
    color: #000000;
}
QToolButton:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #330000, stop:0.25 #660000, stop:0.5 #990000,
        stop:0.75 #cc0000, stop:1 #ff0000) !important;
}
QToolButton:checked, QToolButton:pressed {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #0000ff, stop:0.25 #ffff00, stop:0.5 #ff00ff,
        stop:0.75 #ff0000, stop:1 #00ff00) !important;
    color: #000000;
    border: 2px solid #ff6600;
}
QPushButton {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #ffff00, stop:0.25 #ff00ff, stop:0.5 #0000ff,
        stop:0.75 #00ff00, stop:1 #ff0000) !important;
    border: 1px solid #ff0000;
    color: #000000;
}
QPushButton:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #ff6600, stop:0.25 #ff8800, stop:0.5 #ffaa00,
        stop:0.75 #ffcc00, stop:1 #ffdd00) !important;
    color: #000000;
}
QPushButton:checked {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #ff0000, stop:0.25 #00ff00, stop:0.5 #0000ff,
        stop:0.75 #ffff00, stop:1 #ff00ff) !important;
    color: #000000;
    border: 2px solid #ff6600;
}
QPushButton:pressed {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #ff00ff, stop:0.25 #ff6600, stop:0.5 #ffff00,
        stop:0.75 #00ff00, stop:1 #0000ff) !important;
    color: #000000;
}
QGroupBox {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #ff0000, stop:0.25 #00ff00, stop:0.5 #0000ff,
        stop:0.75 #ffff00, stop:1 #ff00ff) !important;
    color: #000000;
    border: 1px solid #ff0000;
}
QLineEdit, QSpinBox, QDoubleSpinBox, QComboBox {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #00ff00, stop:0.25 #ffff00, stop:0.5 #ff00ff,
        stop:0.75 #ff0000, stop:1 #0000ff) !important;
    color: #000000;
    border: 1px solid #ff0000;
}
QComboBox::drop-down {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #0000ff, stop:0.25 #ffff00, stop:0.5 #ff00ff,
        stop:0.75 #ff0000, stop:1 #00ff00) !important;
}
QCheckBox, QRadioButton {
    color: #ff6600;
}
QCheckBox::indicator, QRadioButton::indicator {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #ff0000, stop:0.25 #ff6600, stop:0.5 #ff6666,
        stop:0.75 #990000, stop:1 #ff0000) !important;
    border: 1px solid #ff0000;
}
QAbstractItemView {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #ff00ff, stop:0.2 #ff0000, stop:0.4 #ffff00,
        stop:0.6 #00ff00, stop:0.8 #0000ff, stop:1 #00ffff) !important;
    color: #000000;
    border: 1px solid #ff0000;
}
QAbstractItemView::item:selected, QAbstractItemView::item:selected:focus {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #0000ff, stop:0.25 #ffff00, stop:0.5 #ff00ff,
        stop:0.75 #ff0000, stop:1 #00ff00) !important;
    color: #000000;
    border: 1px solid #ff6600;
}
QAbstractItemView::item:hover {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #ff6600, stop:0.2 #ff8800, stop:0.4 #ffaa00,
        stop:0.6 #ffcc00, stop:0.8 #ffdd00, stop:1 #ff6600) !important;
}
QTreeView, QTreeWidget, QListWidget, QListView, QTableWidget {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #00ff00, stop:0.2 #ff0000, stop:0.4 #ffff00,
        stop:0.6 #ff00ff, stop:0.8 #0000ff, stop:1 #00ffff) !important;
    border: 1px solid #ff0000;
}
QHeaderView::section {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #ff6600, stop:0.25 #ff00ff, stop:0.5 #ffff00,
        stop:0.75 #00ff00, stop:1 #0000ff) !important;
    color: #000000;
    border: 1px solid #ff6600;
}
QSplitter::handle {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #ff0000, stop:1 #00ff00) !important;
}
QProgressBar {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #ff0000, stop:0.25 #ff6600, stop:0.5 #ffff00,
        stop:0.75 #00ff00, stop:1 #0000ff) !important;
    border: 1px solid #ff0000;
    color: #000000;
}
QProgressBar::chunk {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #00ff00, stop:0.5 #ff0000, stop:1 #ffff00) !important;
    border: 1px solid #ff6600;
}
QDialog {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #ff00ff, stop:0.2 #ff0000, stop:0.4 #ffff00,
        stop:0.6 #00ff00, stop:0.8 #0000ff, stop:1 #00ffff) !important;
}
QToolTip {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #ff0000, stop:0.25 #00ff00, stop:0.5 #0000ff,
        stop:0.75 #ffff00, stop:1 #ff00ff) !important;
    color: #000000;
    border: 1px solid #ff0000;
}
QFrame, QStackedWidget, QScrollArea, QTabWidget, QTabWidget::pane, QSplitter, QTableCornerButton {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #00ffff, stop:0.2 #ff0000, stop:0.4 #ffff00,
        stop:0.6 #ff00ff, stop:0.8 #00ff00, stop:1 #0000ff) !important;
}
QWidget {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #ff0000, stop:0.2 #00ff00, stop:0.4 #0000ff,
        stop:0.6 #ffff00, stop:0.8 #ff00ff, stop:1 #00ffff) !important;
    color: #000000;
}
